Object.assign(window.TEM8_DICTIONARY, {"celebrated":{"oxford":{"phon":"ˈselɪbreɪtɪd","pos":"adjective","senses":[{"en":"famous for having good qualities","cn":"著名的；闻名的；驰名的","ex":{"en":"a celebrated painter","cn":"著名的画家"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"著名的;有名的；受人敬仰的","en":"A celebrated person or thing is famous and much admired.","ex":{"en":"He was soon one of the most celebrated young painters in England","cn":"不久他就成了英格兰最负盛名的年轻画家之一。"}}]},"media":{"uk":"media/uk/celebrated__gb_1.mp3","us":"media/us/celebrated__us_1.mp3"},"examples":[{"en":"a celebrated painter","cn":"著名的画家"},{"en":"a celebrated actress","cn":"著名女演员"}],"base":"celebrate"},"ceilings":{"lemma":"ceiling","media":{"uk":"media/uk/ceiling__gb_1.mp3","us":"media/us/ceiling__us_1.mp3"}},"celebrating":{"lemma":"celebrate"},"certainly":{"media":{"uk":"media/uk/certainly__gb_1.mp3","us":"media/us/certainly__us_1.mp3"},"oxford":{"phon":"ˈsɜːtnli","pos":"adverb","senses":[{"en":"without doubt","cn":"无疑；肯定","lab":"British English","ex":{"en":"Without treatment, she will almost certainly die.","cn":"要是不治疗，她十有八九会死。"}},{"en":"of course","cn":"当然；行","ex":{"en":"‘May I see your passport, Mr Scott?’ ‘Certainly.’","cn":"“斯科特先生，请出示您的护照好吗？”“当然可以。”"}}]},"collins":{"senses":[{"pos":"ADV-GRADED 副词","cn":"当然;肯定","en":"You use certainly to emphasize what you are saying when you are making a statement.","ex":{"en":"The public is certainly getting tired of hearing about it","cn":"关于此事，公众当然已经听腻了。"}},{"pos":"ADV 副词","cn":"(表示同意)当然，行，没问题","en":"You use certainly when you are agreeing with what someone has said.","ex":{"en":"'In any case you remained friends.' — 'Certainly.'","cn":"“无论如何，你们都是好朋友吧。”——“那当然。”"}},{"pos":"ADV as reply 副词","cn":"当然不","en":"You say certainly not when you want to say 'no' in a strong way.","ex":{"en":"'Perhaps it would be better if I withdrew altogether.' — 'Certainly not!'","cn":"“也许，我完全退出更好吧。”——“当然不是！”"}}]},"examples":[{"en":"‘May I see your passport, Mr Scott?’ ‘Certainly.’ “","cn":"斯科特先生，请出示您的护照好吗？” “当然可以。”"},{"en":"‘Do you think all this money will change your life?’ ‘Certainly not.’ “","cn":"你认为这些钱会改变你的生活吗？” “当然不会。”"}]},"cellular":{"oxford":{"phon":"ˈseljələ(r)","pos":"adjective","senses":[{"en":"connected with or consisting of the cells of plants or animals","cn":"细胞的；由细胞组成的","ex":{"en":"cellular structure/processes","cn":"细胞结构／变化过程"}},{"en":"connected with a phone system that works by radio instead of wires","cn":"（无线电话）蜂窝状的","ex":{"en":"a cellular network","cn":"蜂窝式网络系统"}},{"en":"loosely woven to make it feel warmer","cn":"网状的；网眼的","lab":"British English","ex":{"en":"cellular blankets","cn":"网眼毯"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"细胞的","en":"Cellular means relating to the cells of animals or plants.","ex":{"en":"Many toxic effects can be studied at the cellular level.","cn":"许多毒效可以从细胞层次上去研究。"}}]},"media":{"uk":"media/uk/cellular__gb_1.mp3","us":"media/us/cellular__us_1.mp3"},"examples":[{"en":"cellular structure/processes","cn":"细胞结构/变化过程"},{"en":"cellular radio","cn":"蜂窝式无线传输系统"}]},"celebrations":{"lemma":"celebration"},"celery":{"media":{"img":["media/ldoce/img/celery.jpg","media/pic/vegetables_garlic_comp.jpg"],"uk":"media/uk/celery__gb_1.mp3","us":"media/us/celery__us_1.mp3"},"oxford":{"phon":"ˈseləri","pos":"noun","senses":[{"en":"a vegetable with long light-green stems that are often eaten raw","cn":"芹菜","lab":"British English","ex":{"en":"a stick of celery","cn":"一根芹菜"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"芹菜","en":"Celery is a vegetable with long pale green stalks. It is eaten raw in salads.","ex":{"en":"...a stick of celery.","cn":"一根芹菜"}}]},"examples":[{"en":"( BrE ) a stick of celery","cn":"一根芹菜"},{"en":"( NAmE ) a stalk of celery","cn":"一根芹菜"}]},"centrally":{"oxford":{"phon":"ˈsentrəli","pos":"adverb","senses":[{"en":"in a place that is easily reached from many areas","cn":"容易到达的；交通方便的；四通八达的","ex":{"en":"The hotel is centrally located for all major attractions.","cn":"这家旅馆位于中心地带，前往所有主要景点都很方便。"}},{"en":"in the centre of an area or object","cn":"在中心的；中央的","ex":{"en":"The science labs are positioned centrally around the school's media centre.","cn":"科学实验室位于学校媒体中心周围。"}},{"en":"controlled by a central organization or system","cn":"集中地：由中央组织或系统控制","ex":{"en":"a centrally planned economy","cn":"中央计划经济"}},{"en":"in an important or significant way","cn":"集中地：以重要或重要的方式","ex":{"en":"He was centrally involved in setting up and developing the organization.","cn":"他主要参与了该组织的建立和发展。"}}]},"media":{"uk":"media/uk/centrally__gb_1.mp3","us":"media/us/centrally__us_1.mp3"},"examples":[{"en":"The hotel is centrally located for all major attractions.","cn":"这家旅馆位于中心地带，前往所有主要景点都很方便。"},{"en":"Is the house centrally heated (= does it have central heating)?","cn":"这房子有中央供暖吗？"}]},"celibate":{"media":{"uk":"media/uk/celibate__gb_1.mp3","us":"media/us/celibate__us_1.mp3"},"oxford":{"phon":"ˈselɪbət","pos":"adjective","senses":[{"en":"not married and not having sex, especially for religious reasons","cn":"（尤指因宗教原因）独身的，不结婚的，没有性生活的","ex":{"en":"celibate priests","cn":"独身的教士"}},{"en":"not having sex","cn":"无性生活的；禁欲的","ex":{"en":"I've been celibate for the past six months.","cn":"我已禁欲六个月。"}},{"en":"a person who has chosen not to marry; a person who never has sex","cn":"独身主义者；禁欲者；从不过性生活的人","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(因宗教信仰)禁欲的，独身的","en":"Someone who is celibate does not marry or have sex, because of their religious beliefs.","ex":{"en":"The Pope bluntly told the world's priests yesterday to stay celibate.","cn":"教皇昨天直言全世界的神父都应该禁欲。"}},{"pos":"ADJ 形容词","cn":"(特定时期)禁欲的，节制性欲的","en":"Someone who is celibate does not have sex during a particular period of their life.","ex":{"en":"I was celibate for two years.","cn":"我有两年没有性生活。"}}]},"examples":[{"en":"I've been celibate for the past six months.","cn":"我已禁欲六个月。"},{"en":"celibate priests","cn":"独身的教士"}]},"certainty":{"media":{"uk":"media/uk/certainty__gb_1.mp3","us":"media/us/certainty__us_1.mp3"},"oxford":{"phon":"ˈsɜːtnti","pos":"noun","senses":[{"en":"the state of being certain","cn":"确信；确实；确定性","g":"[uncountable]","ex":{"en":"There is no certainty that the president's removal would end the civil war.","cn":"总统下台是否会结束内战现在还很难说。"}},{"en":"a thing that is certain","cn":"确实的事；必然的事","g":"[countable]","ex":{"en":"political/moral certainties","cn":"政治上／道德上确定无疑的事"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"确定;有把握","en":"Certainty is the state of being definite or of having no doubts at all about something.","ex":{"en":"I have told them with absolute certainty there'll be no change of policy","cn":"我已经十分肯定地告诉他们，政策不会变。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"必然(性);肯定(性)","en":"Certainty is the fact that something is certain to happen.","ex":{"en":"A general election became a certainty three weeks ago.","cn":"3个星期前举行普选已确定无疑。"}},{"pos":"N-COUNT 可数名词","cn":"确定无疑的事情;必然的事","en":"Certainties are things that nobody has any doubts about.","ex":{"en":"There are no certainties in modern Europe","cn":"当代欧洲没有什么是确定无疑的。"}}]},"examples":[{"en":"There is no certainty that the president's removal would end the civil war.","cn":"总统下台是否会结束内战现在还很难说。"},{"en":"I can't say with any certainty where I'll be next week.","cn":"我不能说准我下周会在什么地方。"}]},"certain":{"media":{"uk":"media/uk/certain__gb_1.mp3","us":"media/us/certain__us_1.mp3"},"oxford":{"phon":"ˈsɜːtn","pos":"adjective","senses":[{"en":"strongly believing something; having no doubts","cn":"确信；确定；无疑","ex":{"en":"I think it was him, but I can't be certain.","cn":"我认为是他，但我不能肯定。"}},{"en":"that you can rely on to happen or to be true","cn":"必定；一定","ex":{"en":"The climbers face certain death if the rescue today is unsuccessful.","cn":"救援行动如果今天不能成功，登山队员必死无疑。"}},{"en":"used to mention a particular thing, person or group without giving any more details about it or them","cn":"（不提及细节时用）某事，某人，某种","ex":{"en":"For certain personal reasons I shall not be able to attend.","cn":"由于某种个人原因，我将不能出席。"}},{"en":"slight; easy to notice, but difficult to describe","cn":"稍微的；些许的；某种程度的","ex":{"en":"That's true, to a certain extent.","cn":"在一定程度上的确如此。"}},{"en":"used with a person’s name to show that the speaker does not know the person","cn":"（与人名连用，表示说话人不认识的人）某位，一位叫…的","lab":"formal","ex":{"en":"It was a certain Dr Davis who performed the operation.","cn":"是一位叫戴维斯的医生做的手术。"}},{"en":"used for talking about some members of a group of people or things without giving their names","cn":"（不提及人或事物的名称时用）某些","ex":{"en":"Certain of those present were unwilling to discuss the matter further.","cn":"某些在场的人不愿意进一步讨论这个问题。"},"pos":"pronoun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"肯定的;有把握的;毫无疑问的","en":"If you are certain about something, you firmly believe it is true and have no doubt about it. If you are not certain about something, you do not have definite knowledge about it.","ex":{"en":"She's absolutely certain she's going to make it in the world","cn":"她坚信自己会出人头地。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"必然的;必定的;肯定的","en":"If you say that something is certain to happen, you mean that it will definitely happen.","ex":{"en":"However, the scheme is certain to meet opposition from fishermen's leaders","cn":"然而，这项计划一定会遭到渔民领袖的反对。"}},{"pos":"ADJ 形容词","cn":"确凿的；无疑的","en":"If you say that something is certain, you firmly believe that it is true, or have definite knowledge about it.","ex":{"en":"One thing is certain, both have the utmost respect for each other","cn":"有一点可以肯定，那就是双方都非常尊重对方。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"确实的;肯定的","en":"If you have certain knowledge, you know that a particular thing is true.","ex":{"en":"He had been there four times to my certain knowledge.","cn":"我确定他去过那儿4次。"}},{"pos":"PHRASE 短语","cn":"确切地;无疑地","en":"If you know something for certain, you have no doubt at all about it.","ex":{"en":"She couldn't know what time he'd go, or even for certain that he'd go at all","cn":"她不知道他何时走，就连他到底走不走都说不准。"}},{"pos":"PHRASE 短语","cn":"确保；保证","en":"If you make certain that something is the way you want or expect it to be, you take action to ensure that it is.","ex":{"en":"Firstly, they must make certain that their pension needs are adequately catered for","cn":"首先，他们得确保他们能获得足够的养老金。"}},{"pos":"ADJ 形容词","cn":"某个;特定的","en":"You use certain to indicate that you are referring to one particular thing, person, or group, although you are not saying exactly which it is.","ex":{"en":"There will be certain people who'll say 'I told you so!'","cn":"一定有人会说：“我怎么跟你说来着！”"}},{"pos":"QUANT 数量词","cn":"某些;一些","en":"When you refer to certain of a group of people or things, you are referring to some particular members of that group.","ex":{"en":"They'll have to give up completely on certain of their studies.","cn":"他们将不得不彻底放弃某些研究。"}},{"pos":"ADJ 形容词","cn":"(用于人名前，表示不认识或了解很少)某个","en":"You can use a certain before the name of a person in order to indicate that you do not know the person or anything else about them.","ex":{"en":"She managed to arrange for them to be hidden in the house of a certain Father Boduen.","cn":"她设法安排他们藏在一个叫博迪恩的神父家里。"}},{"pos":"ADJ 形容词","cn":"(品质、特点等)一定程度上的，有点儿","en":"You use a certain to indicate that something such as a quality or condition exists, and often to suggest that it is not great in amount or degree.","ex":{"en":"That was the very reason why he felt a certain bitterness","cn":"那就是为什么他感到有些痛苦。"}}]},"examples":[{"en":"I think there's a bus at 8 but you'd better call to make certain.","cn":"好像 8 点有一班公共汽车，不过你最好打电话弄清楚。"},{"en":"The climbers face certain death if the rescue today is unsuccessful.","cn":"救援行动如果今天不能成功，登山队员必死无疑。"}]},"centre":{"media":{"img":["media/pic/circles_comp.jpg","media/thumb/circles2.jpg"],"uk":"media/uk/centre__gb_1.mp3","us":"media/us/centre__us_1.mp3"},"oxford":{"phon":"ˈsentə(r)","pos":"noun","senses":[{"en":"the middle point or part of something","cn":"中心点；中心；正中；中央","g":"[countable]","lab":"figurative","sc":"middle","ex":{"en":"He walked to the centre of the circle.","cn":"他走到了圆圈的中心。"}},{"en":"the main part of a town or city where there are a lot of shops and offices","cn":"（市镇的）中心区","g":"[countable]","lab":"especially British English","sc":"town/city","ex":{"en":"We both work in the city centre.","cn":"我们俩都在市中心工作。"}},{"en":"a place or an area where a lot of people live; a place where a lot of business or cultural activity takes place","cn":"人口集中的地区；商业中心区；文化中心区","g":"[countable]","sc":"town/city","ex":{"en":"major urban/industrial centres","cn":"主要城市／工业中心"}},{"en":"a building or place used for a particular purpose or activity","cn":"中心；活动中心","g":"[countable]","sc":"building","ex":{"en":"a shopping/community/health/fitness centre","cn":"购物／社区／卫生服务／健身中心"}},{"en":"a place where a particular kind of work is done extremely well","cn":"居领先地位的中心；（某领域中成绩突出的）中心","g":"[countable]","sc":"of excellence","ex":{"en":"Darlington could become a regional centre of excellence for nursery nurse training.","cn":"达灵顿可以成为区域托儿所护士培训的卓越中心。"}},{"en":"the point towards which people direct their attention","cn":"中心；聚集点","g":"[countable, usually singular]","sc":"of attention","ex":{"en":"Children like to be the centre of attention.","cn":"小孩子喜欢受到大家的关注。"}},{"en":"a moderate (= middle) political position or party, between the extremes of left-wing and right-wing parties","cn":"中间派；中间党","g":"[singular]","sc":"in politics","ex":{"en":"a party of the centre","cn":"中间党派"}},{"en":"a player or position in the middle of the pitch, court, etc.","cn":"中锋；中锋位置","g":"[countable]","sc":"in sport"},{"en":"to be the person or thing around which most activity takes place; to make somebody/something the central person or thing","cn":"以…为中心；使…成为中心","g":"[intransitive, transitive]","ex":{"en":"State occasions always centred around the king.","cn":"国家庆典总是以国王为中心。"},"pos":"verb"},{"en":"to take place mainly in or around the place mentioned","cn":"集中在；以…为中心","g":"[intransitive]","ex":{"en":"Most of the fighting was centred in the north of the capital.","cn":"战斗大多集中在首都北部。"},"pos":"verb"},{"en":"to move something so that it is in the centre of something else","cn":"把…放在中央","g":"[transitive]","ex":{"en":"This button will centre the image on the page.","cn":"这个按钮可使图像置于页面中央。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(会议、活动、服务等的)中心","en":"A centre is a building where people have meetings, take part in a particular activity, or get help of some kind.","ex":{"en":"We went to a party at the leisure centre","cn":"我们去休闲中心参加一个聚会。"}},{"pos":"N-COUNT 可数名词","cn":"(工业、活动等的)中心","en":"If an area or town is a centre for an industry or activity, that industry or activity is very important there.","ex":{"en":"London is also the major international insurance centre.","cn":"伦敦也是重要的国际保险中心。"}},{"pos":"N-COUNT 可数名词","cn":"中心;中央;中部","en":"The centre of something is the middle of it.","ex":{"en":"A large wooden table dominates the centre of the room","cn":"一张大木桌摆在房间正中央。"}},{"pos":"N-COUNT 可数名词","cn":"(市镇的)商业中心，闹市区，繁华地带","en":"The centre of a town or city is the part where there are the most shops and businesses and where a lot of people come from other areas to work or shop.","ex":{"en":"...the city centre.","cn":"市中心"}},{"pos":"N-COUNT 可数名词","cn":"中心;核心","en":"If something or someone is at the centre of a situation, they are the most important thing or person involved.","ex":{"en":"...the man at the centre of the controversy","cn":"处于争论焦点的人"}},{"pos":"N-COUNT 可数名词","cn":"(关注的)中心，焦点;中心人物","en":"If someone or something is the centre of attention or interest, people are giving them a lot of attention.","ex":{"en":"The rest of the cast was used to her being the centre of attention","cn":"她总是人们关注的焦点，其他演职人员对此已经习以为常。"}},{"pos":"N-SING 单数名词","cn":"(政党)中间派，中立派","en":"In politics, the centre refers to groups and their beliefs, when they are considered to be neither left-wing nor right-wing.","ex":{"en":"The Democrats have become a party of the centre.","cn":"民主党成了中立的党派。"}},{"pos":"VERB 动词","cn":"将…放在正中央","en":"If you centre something, you move it so that it is at the centre of something else.","ex":{"en":"Centre the design on the cloth before you start.","cn":"在开始前，将图案放在布的正中间。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）以…为中心;（使）注意力集中于","en":"If something centres or is centred on a particular thing or person, that thing or person is the main subject of attention.","ex":{"en":"...a plan which centred on academic achievement and personal motivation","cn":"重点强调学术成就和个人兴趣的计划"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)主要发生在；（使）集中于","en":"If an industry or event is centred in a place, or if it centres there, it takes place to the greatest extent there.","ex":{"en":"The fighting has been centred around the town of Vucovar","cn":"战斗主要集中在武科瓦尔镇周围。"}}]},"examples":[{"en":"Small towns in South India serve as economic and cultural centres for the surrounding villages.","cn":"印度南部的小城镇是周围村庄的经济文化中心。"},{"en":"The prime minister is at the centre of a political row over leaked Cabinet documents.","cn":"首相成了内阁文件泄秘政治风波的中心人物。"}]},"ceremony":{"oxford":{"phon":"ˈserəməni","pos":"noun","senses":[{"en":"a public or religious occasion that includes a series of formal or traditional actions","cn":"典礼；仪式","g":"[countable]","lab":"especially North American English","ex":{"en":"More than 1 000 people attended the ceremony.","cn":"超过 1 000 人出席了该仪式。"}},{"en":"formal behaviour; traditional actions and words used on particular formal occasions","cn":"礼节；礼仪；礼貌","g":"[uncountable]","ex":{"en":"The royal guests were welcomed with pomp and ceremony.","cn":"皇家宾客受到隆重而隆重的欢迎。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"仪式；典礼","en":"A ceremony is a formal event such as a wedding.","ex":{"en":"...his grandmother's funeral, a private ceremony attended only by the family","cn":"他祖母的葬礼，只有家人参加的私人仪式"}},{"pos":"N-UNCOUNT 不可数名词","cn":"礼节;礼数;客套","en":"Ceremony consists of the special things that are said and done on very formal occasions.","ex":{"en":"The Republic was proclaimed in public with great ceremony.","cn":"共和国在公开场合非常隆重地宣布成立。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"很快地;随意地","en":"If you do something without ceremony, you do it quickly and in a casual way.","ex":{"en":"'Is Hilton here?' she asked without ceremony.","cn":"“希尔顿在吗？”她随口问道。"}}]},"media":{"uk":"media/uk/ceremony__gb_1.mp3","us":"media/us/ceremony__us_1.mp3"},"examples":[{"en":"He found himself pushed without ceremony out of the house and the door slammed in his face.","cn":"他被毫不客气地推出了房子，门砰的一声当着他的面关上了。"},{"en":"Please don't stand on ceremony (= Please be natural and relaxed) with me.","cn":"请别跟我讲客套。"}]},"cell":{"media":{"uk":"media/uk/cell__gb_1.mp3","us":"media/us/cell__us_1.mp3","img":["media/ldoce/img/cell.jpg"]},"oxford":{"phon":"sel","pos":"noun","senses":[{"en":"the smallest unit of living matter that can exist on its own. All plants and animals are made up of cells.","cn":"细胞","ex":{"en":"red and white blood cells","cn":"红细胞和白细胞"}},{"en":"a room for one or more prisoners in a prison or police station","cn":"单间牢房；牢房","ex":{"en":"He spent a night in a prison cell.","cn":"他在牢房里待了一夜。"}},{"en":"a small room without much furniture in which a monk or nun lives","cn":"（修道士或修女住的）小房间"},{"en":"each of the small sections that together form a larger structure, for example a honeycomb","cn":"（大结构中的）小隔室（如蜂房巢室）"},{"en":"a device for producing an electric current, for example by the action of chemicals or light","cn":"电池","ex":{"en":"a photoelectric cell","cn":"光电池"}},{"en":"a small group of people who work as part of a larger political organization, especially secretly","cn":"（尤指秘密的）政治小组，基层组织","ex":{"en":"a terrorist cell","cn":"恐怖分子小组"}},{"en":"one of the small squares in a spreadsheet computer program in which you enter a single piece of data","cn":"（计算机电子表格的）单元格"},{"en":"a phone that does not have wires and works by radio, and that you can carry with you and use anywhere","cn":"移动电话；手机","lab":"especially North American English, informal，，","ex":{"en":"Call me on my cell.","cn":"打我手机。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"细胞","en":"A cell is the smallest part of an animal or plant that is able to function independently. Every animal or plant is made up of millions of cells.","ex":{"en":"Those cells divide and give many other different types of cells.","cn":"那些细胞分裂，产生出许多不同种类的细胞。"}},{"pos":"N-COUNT 可数名词","cn":"单人牢房；(修道院的)单人小室","en":"A cell is a small room in which a prisoner is locked. A cell is also a small room in which a monk or nun lives."},{"pos":"N-COUNT 可数名词","cn":"(大型组织中的)基层组织","en":"You can refer to a small group of people within a larger organization as a cell .","ex":{"en":"...Communist Party cells.","cn":"共产党的基层组织"}}]},"examples":[{"en":"a terrorist cell","cn":"恐怖分子小组"},{"en":"blood cells","cn":"血细胞"}]},"celebrate":{"oxford":{"phon":"ˈselɪbreɪt","pos":"verb","senses":[{"en":"to show that a day or an event is important by doing something special on it","cn":"庆祝；庆贺","g":"[intransitive, transitive]","ex":{"en":"Jake's passed his exams. We're going out to celebrate.","cn":"杰克已通过考试，我们要外出庆祝一下。"}},{"en":"to perform a religious ceremony, especially the Christian communion service","cn":"主持宗教仪式（尤指圣餐）","g":"[transitive]"},{"en":"to praise somebody/something","cn":"赞美；颂扬；歌颂","g":"[transitive]","lab":"formal","ex":{"en":"songs that celebrate the joys of romantic love","cn":"颂扬浪漫爱情的喜悦的歌曲"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"庆祝","en":"If you celebrate, you do something enjoyable because of a special occasion or to mark someone's success.","ex":{"en":"I was in a mood to celebrate","cn":"我很想庆祝一下。"}},{"pos":"VERB 动词","cn":"成立(…年);庆祝(周年)","en":"If an organization or country is celebrating an anniversary, it has existed for that length of time and is doing something special because of it.","ex":{"en":"The Society is celebrating its tenth anniversary this year.","cn":"这个协会今年将举办成立10周年庆典。"}},{"pos":"VERB 动词","cn":"主持(圣餐或弥撒)","en":"When priests celebrate Holy Communion or Mass, they officially perform the actions and ceremonies that are involved.","ex":{"en":"Pope John Paul celebrated mass today in a city in central Poland.","cn":"教皇保罗二世今天在波兰中部的一个城市主持了弥撒。"}}]},"media":{"uk":"media/uk/celebrate__gb_1.mp3","us":"media/us/celebrate__us_1.mp3"},"examples":[{"en":"a movie celebrating the life and work of Martin Luther King","cn":"颂扬马丁 · 路德 · 金生平事迹的影片"},{"en":"Jake's passed his exams. We're going out to celebrate.","cn":"杰克已通过考试，我们要外出庆祝一下。"}]},"cellar":{"media":{"uk":"media/uk/cellar__gb_1.mp3","us":"media/us/cellar__us_1.mp3"},"oxford":{"phon":"ˈselə(r)","pos":"noun","senses":[{"en":"an underground room often used for storing things","cn":"地窖；地下室","ex":{"en":"We looked all over the house, even down in the coal cellar.","cn":"我们找遍了整栋房子，甚至连贮煤的地窖也找过了。"}},{"en":"an underground room where wine is stored; the wine stored in this room","cn":"酒窖；贮藏在酒窖里的酒"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地窖;地下室","en":"A cellar is a room underneath a building, which is often used for storing things in.","ex":{"en":"The box of papers had been stored in a cellar at the family home.","cn":"那箱文件一直藏在家中的地窖里。"}},{"pos":"N-COUNT 可数名词","cn":"(私人或饭店的)酒窖","en":"A person's or restaurant's cellar is the collection of different wines that they have.","ex":{"en":"...the restaurant's extensive wine cellar.","cn":"饭店藏酒品种繁多的酒窖"}}]},"examples":[{"en":"a coal cellar","cn":"贮煤地窖"}]},"ceiling":{"media":{"uk":"media/uk/ceiling__gb_1.mp3","us":"media/us/ceiling__us_1.mp3"},"oxford":{"phon":"ˈsiːlɪŋ","pos":"noun","senses":[{"en":"the top inside surface of a room","cn":"天花板；顶棚","ex":{"en":"a large room with a high ceiling","cn":"屋顶很高的大房间"}},{"en":"the highest limit or amount of something","cn":"最高限度；上限；最大限量","ex":{"en":"The government has decided to lift price ceilings on bread and milk.","cn":"政府已决定取消对面包和牛奶的最高限价。"}},{"en":"the greatest height at which a particular aircraft is able to fly","cn":"升限；最高飞行限度","lab":"specialist","ex":{"en":"an aircraft with a ceiling of 20 000 feet","cn":"升限为 20 000 英尺的飞机"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"屋顶;天花板","en":"A ceiling is the horizontal surface that forms the top part or roof inside a room.","ex":{"en":"The rooms were spacious, with tall windows and high ceilings","cn":"房间很宽敞，窗户和天花板都很高。"}},{"pos":"N-COUNT 可数名词","cn":"(官方定的价格、工资等的)上限，最高限额","en":"A ceiling on something such as prices or wages is an official upper limit that cannot be broken.","ex":{"en":"...an informal agreement to put a ceiling on salaries","cn":"对工资封顶的非正式协议"}},{"pos":"N-COUNT 可数名词","cn":"最高飞行限度;升限","en":"A ceiling is the greatest height at which a particular aircraft can fly safely."}]},"examples":[{"en":"She lay on her back staring up at the ceiling.","cn":"她仰卧着凝视天花板。"},{"en":"a large room with a high ceiling","cn":"屋顶很高的大房间"}]},"century":{"media":{"uk":"media/uk/century__gb_1.mp3","us":"media/us/century__us_1.mp3"},"oxford":{"phon":"ˈsentʃəri","pos":"noun","senses":[{"en":"a period of 100 years","cn":"100 年；百年","ex":{"en":"A century ago, Valparaiso was the country's main port.","cn":"一个世纪前，瓦尔帕莱索是该国的主要港口。"}},{"en":"any of the periods of 100 years before or after the birth of Christ","cn":"世纪","ex":{"en":"the twentieth century (= AD 1901–2000 or 1900–1999)","cn":"20 世纪"}},{"en":"a score of 100 runs by one player","cn":"（一个运动员所得的）100 分"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"世纪","en":"A century is a period of a hundred years that is used when stating a date. For example, the 19th century was the period from 1801 to 1900.","ex":{"en":"...celebrated figures of the late eighteenth century.","cn":"18世纪晚期的名人"}},{"pos":"N-COUNT 可数名词","cn":"一百年","en":"A century is any period of a hundred years.","ex":{"en":"The drought there is the worst in a century.","cn":"这是一百年来最严重的旱灾。"}},{"pos":"N-COUNT 可数名词","cn":"(板球中一名击球手获得的)一百分，一百多分","en":"In cricket, a century is a score of one hundred runs or more by one batsman."}]},"examples":[{"en":"the 20th century (= AD 1901–2000 or 1900–1999) * 20","cn":"世纪"},{"en":"the 20th century (= AD 1901–2000 or 1900–1999)","cn":""}]},"cement":{"media":{"uk":"media/uk/cement__gb_1.mp3","us":"media/us/cement__us_1.mp3"},"oxford":{"phon":"sɪˈment","pos":"noun","senses":[{"en":"a grey powder made by burning clay and lime that sets hard when it is mixed with water. Cement is used in building to stick stones and bricks together and to make very hard surfaces.","cn":"水泥","ex":{"en":"Use a mixture of one part cement to four parts sand.","cn":"使用一份水泥和四份沙子的混合物。"}},{"en":"the hard substance that is formed when cement becomes dry and hard","cn":"（干燥后硬化的）水泥","ex":{"en":"a floor of cement","cn":"水泥地板"}},{"en":"a soft substance that becomes hard when dry and is used for sticking things together or filling in holes","cn":"胶合剂；胶接剂；黏固剂","ex":{"en":"dental cement (= for filling holes in teeth)","cn":"补牙用的黏固剂"}},{"en":"something that joins people together in a common interest","cn":"（共同利益联合起来的）纽带，凝聚力","lab":"formal","ex":{"en":"values that are the cement of society","cn":"使社会具有凝聚力的价值观念"}},{"en":"to join two things together using cement, glue (= a sticky substance), etc.","cn":"（用水泥、胶等）黏结，胶合","g":"[often passive]","pos":"verb"},{"en":"to make a relationship, an agreement, etc. stronger","cn":"加强，巩固（关系、协定等）","ex":{"en":"The president's visit was intended to cement the alliance between the two countries.","cn":"总统的访问是为了加强两国的联盟。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"水泥","en":"Cement is a grey powder which is mixed with sand and water in order to make concrete.","ex":{"en":"...a mixture of wet sand and cement.","cn":"湿沙子和水泥的混合料"}},{"pos":"N-UNCOUNT 不可数名词","cn":"同 concrete","en":"Cement is the same as concrete .","ex":{"en":"...the hard cold cement floor.","cn":"又硬又冷的混凝土地面"}},{"pos":"N-UNCOUNT 不可数名词","cn":"胶接剂;接合剂","en":"Glue that is made for sticking particular substances together is sometimes called cement .","ex":{"en":"Stick the pieces on with tile cement.","cn":"用瓷砖胶把它们一块块贴上去。"}},{"pos":"VERB 动词","cn":"巩固;加强","en":"Something that cements a relationship or agreement makes it stronger.","ex":{"en":"Nothing cements a friendship between countries so much as trade.","cn":"贸易最能增强国家间的友谊。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"起巩固作用的因素;加强剂；纽带","en":"The cement of a relationship or agreement is something that makes it stronger and more long-lasting.","ex":{"en":"...the power of the party, once the cement that held the Soviet Union together","cn":"党的力量，曾经是保持苏联团结的黏合剂"}},{"pos":"VERB 动词","cn":"把…黏合;使黏结","en":"If things are cemented together, they are stuck or fastened together.","ex":{"en":"Most artificial joints are cemented into place.","cn":"多数人工关节是用骨水泥固定到位的。"}}]},"examples":[{"en":"The President's visit was intended to cement the alliance between the two countries.","cn":"总统的访问是为了加强两国的联盟。"},{"en":"values which are the cement of society","cn":"使社会具有凝聚力的价值观念"}]},"central":{"media":{"uk":"media/uk/central__gb_1.mp3","us":"media/us/central__us_1.mp3"},"oxford":{"phon":"ˈsentrəl","pos":"adjective","senses":[{"en":"in the centre of an area or object","cn":"在中心的；中央的","ex":{"en":"central London","cn":"伦敦中心区"}},{"en":"easily reached from many areas","cn":"容易到达的；交通方便的；四通八达的","ex":{"en":"The flat is very central—just five minutes from Princes Street.","cn":"这座公寓位于市中心，离王子街只需要五分钟。"}},{"en":"most important","cn":"最重要的；首要的；主要的","ex":{"en":"The central issue is that of widespread racism.","cn":"最重要的问题是种族主义到处泛滥。"}},{"en":"having power or control over other parts","cn":"起支配作用的；有控制力的","ex":{"en":"the central committee (= of a political party)","cn":"（政党的）中央委员会"}},{"en":"produced with the centre of the tongue in a higher position than the front or the back, for example /ɜː/ in bird","cn":"中央的（发音时舌高点在口腔中间位置）","lab":"phonetics"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"中央的;中心的","en":"Something that is central is in the middle of a place or area.","ex":{"en":"...Central America's Caribbean coast","cn":"中美洲加勒比海沿岸"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"位于中央地带的;处于中心的;四通八达的","en":"A place that is central is easy to reach because it is in the centre of a city, town, or particular area.","ex":{"en":"...a central location in the capital.","cn":"首都的中心地带"}},{"pos":"ADJ 形容词","cn":"中央的;有最高决策权的","en":"A central group or organization makes all the important decisions that are followed throughout a larger organization or a country.","ex":{"en":"There is a lack of trust towards the central government in Rome.","cn":"人们对罗马的中央政府缺乏信任。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"最重要的;核心的","en":"The central person or thing in a particular situation is the most important one.","ex":{"en":"Black dance music has been central to mainstream pop since the early '60s.","cn":"自上世纪60年代以来，黑人舞曲一直是主流流行乐的核心。"}}]},"examples":[{"en":"The hotel is centrally located for all major attractions.","cn":"这家旅馆位于中心地带，前往所有主要景点都很方便。"},{"en":"The flat is very central — just five minutes from Princes Street.","cn":"这座公寓位于市中心，离王子街只需要五分钟。"}]},"ceremonies":{"lemma":"ceremony"},"celsius":{"oxford":{"phon":"ˈselsiəs","pos":"adjective","senses":[{"en":"of or using a scale of temperature in which water freezes at 0° and boils at 100°","cn":"摄氏的","ex":{"en":"It will be a mild night, around nine degrees Celsius.","cn":"晚间天气温和，温度约九摄氏度。"}},{"en":"a scale of temperature in which water freezes at 0° and boils at 100°","cn":"摄氏温度","ex":{"en":"temperatures in Celsius and Fahrenheit","cn":"摄氏温度和华氏温度"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"℃. 摄氏(温度)的（符号为℃）","en":"Celsius is a scale for measuring temperature, in which water freezes at 0 degrees and boils at 100 degrees. It is represented by the symbol →see usage note at:","ex":{"en":"Highest temperatures 11º Celsius, that's 52º Fahrenheit.","cn":"最高温度11摄氏度，即52华氏度。"}}]},"media":{"uk":"media/uk/celsius__gb_1.mp3","us":"media/us/celsius__us_1.mp3"},"examples":[{"en":"It will be a mild night, around nine degrees Celsius.","cn":"晚间天气温和，温度约九摄氏度。"},{"en":"temperatures in Celsius and Fahrenheit","cn":"摄氏和华氏温度"}]},"cents":{"lemma":"cent","media":{"uk":"media/uk/cent__gb_1.mp3","us":"media/us/cent__us_1.mp3"}},"cent":{"media":{"uk":"media/uk/cent__gb_1.mp3","us":"media/us/cent__us_1.mp3"},"oxford":{"phon":"sent","pos":"noun","senses":[{"en":"a coin and unit of money worth 1% of the main unit of money in many countries, for example of the US dollar or of the euro","cn":"分（辅币单位，相当于许多国家主币面值的 1%，如美元或欧元的 1%）；分币","ex":{"en":"A one-minute phone call to the UK cost 10 cents.","cn":"打一分钟电话到英国要花 10 美分。"}},{"en":"century","cn":"世纪","ex":{"en":"in the 20th cent.","cn":"在 20 世纪"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"分(美元、欧元等的货币单位)","en":"A cent is a small unit of money worth one hundredth of some currencies, for example the dollar and the euro.","ex":{"en":"A cup of rice which cost thirty cents a few weeks ago is now being sold for up to one dollar","cn":"几个星期前卖30美分一杯的米饭，如今卖到1美元。"}}]}},"ceo":{"media":{"uk":"media/uk/ceo__gb_1.mp3","us":"media/us/ceo__us_1.mp3"},"oxford":{"phon":"ˌsiː iː ˈəʊ","pos":"noun","senses":[{"en":"the person with the highest rank in a business company (the abbreviation for ‘chief executive officer’)","cn":"首席执行官（全写为 chief executive officer）"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"首席执行官;执行总裁","en":"CEO is an abbreviation for (缩略=) chief executive officer ."}]}},"center":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/center__gb_1.mp3","us":"media/us/center__us_1.mp3"},"oxford":{"phon":"ˈsentə(r)","pos":"noun","senses":[{"en":"the middle point or part of something","cn":"中心点；中心；正中；中央","g":"[countable]","ex":{"en":"He walked to the center of the circle.","cn":"他走到了圆圈的中心。"}},{"en":"the main part of a town or city where there are a lot of shops and offices","cn":"（市镇的）中心区","g":"[countable]","lab":"especially British English","ex":{"en":"We both work in the city center.","cn":"我们都在市中心工作。"}},{"en":"a place or an area where a lot of people live; a place where a lot of business or cultural activity takes place","cn":"人口集中的地区；商业中心区；文化中心区","g":"[countable]","ex":{"en":"major urban/industrial centers","cn":"主要城市/工业中心"}},{"en":"a building or place used for a particular purpose or activity","cn":"中心；活动中心","g":"[countable]","ex":{"en":"a shopping/sports/leisure/community center","cn":"购物/运动/休闲/社区中心"}},{"en":"a place where a particular kind of work is done extremely well","cn":"居领先地位的中心；（某领域中成绩突出的）中心","g":"[countable]","ex":{"en":"The university is recognized as an international center of excellence for training dentists.","cn":"该大学被公认为国际牙医培训卓越中心。"}},{"en":"the point towards which people direct their attention","cn":"中心；聚集点","g":"[countable, usually singular]","ex":{"en":"Children like to be the center of attention.","cn":"孩子们喜欢成为关注的焦点。"}},{"en":"a moderate (= middle) political position or party, between the extremes of left-wing and right-wing parties","cn":"中间派；中间党","g":"[singular]","ex":{"en":"a party of the center","cn":"中心党"}},{"en":"a player or position in the middle of the pitch, court, etc.","cn":"中锋；中锋位置","g":"[countable]"},{"en":"to be the person or thing around which most activity takes place; to make somebody/something the central person or thing","cn":"以…为中心；使…成为中心","g":"[intransitive, transitive]","ex":{"en":"Conversation centered around their wedding plans.","cn":"谈话集中在他们的婚礼计划上。"},"pos":"verb"},{"en":"to take place mainly in or around the place mentioned","cn":"集中在；以…为中心","g":"[intransitive]","ex":{"en":"Most of the fighting was centered in the north of the capital.","cn":"大部分战斗集中在首都北部。"},"pos":"verb"},{"en":"to move something so that it is in the center of something else","cn":"把…放在中央","g":"[transitive]","ex":{"en":"This button will center the image on the page.","cn":"此按钮将使图像在页面上居中。"},"pos":"verb"}]}},"celebration":{"oxford":{"phon":"ˌselɪˈbreɪʃn","pos":"noun","senses":[{"en":"a special event that people organize in order to celebrate something","cn":"庆典；庆祝活动","g":"[countable]","ex":{"en":"The occasion was the 40th anniversary celebrations of the orchestra.","cn":"那次活动是管弦乐队成立 40 周年庆典。"}},{"en":"the act of celebrating something","cn":"庆祝；颂扬","g":"[uncountable, countable]","ex":{"en":"Her triumph was a cause for celebration.","cn":"她的胜利是庆祝的理由。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"庆祝活动;庆典","en":"A celebration is a special enjoyable event that people organize because something pleasant has happened or because it is someone's birthday or anniversary.","ex":{"en":"I can tell you, there was a celebration in our house that night.","cn":"告诉你，那天晚上我家开了个庆祝会。"}},{"pos":"N-SING 单数名词","cn":"赞扬;赞美;颂扬","en":"The celebration of something is praise and appreciation which is given to it.","ex":{"en":"This was not a memorial service but a celebration of his life","cn":"这不是在开追悼会，而是在颂扬他的一生。"}}]},"media":{"uk":"media/uk/celebration__gb_1.mp3","us":"media/us/celebration__us_1.mp3"},"examples":[{"en":"The service was a celebration of his life (= praised what he had done in his life).","cn":"举行的宗教礼仪颂扬了他的一生。"},{"en":"Her triumph was a cause for celebration.","cn":"她的胜利是庆祝的理由。"}]},"certifying":{"oxford":{"phon":"ˈsɜːtɪfaɪ","pos":"verb","senses":[{"en":"( formal ) to state officially, especially in writing, that sth is true （","cn":"尤指书面）证明，证实"},{"en":"to give sb an official document proving that they are qualified to work in a particular profession","cn":"颁发（或授予）专业合格证书"}]}},"centrifuges":{"oxford":{"phon":"ˈsentrɪfjuːdʒ","pos":"noun","senses":[{"en":"a machine with a part that spins around to separate substances, for example liquids from solids, by forcing the heavier substance to the outer edge","cn":"离心机；离心分离机；离心过滤机"}]}},"centuries":{"lemma":"century"},"cells":{"lemma":"cell"},"centres":{"lemma":"centre"},"celebrities":{"lemma":"celebrity"},"ceramics":{"oxford":{"phon":"səˈræmɪk","pos":"noun","senses":[{"en":"a pot or other object made of clay that has been made permanently hard by heat","cn":"陶瓷制品；陶瓷器"},{"en":"the art of making and decorating ceramics","cn":"制陶艺术；陶瓷装潢艺术"}]},"media":{"uk":"media/ldoce/hwd/bre/a/brelasdeceramics.mp3","us":"media/ldoce/hwd/ame/6/ceramics.mp3"},"examples":[{"en":"an exhibition of ceramics","cn":"陶瓷器展览"}]},"censure":{"collins":{"senses":[{"pos":"VERB 动词","cn":"严厉批评;指责","en":"If you censure someone for something that they have done, you tell them that you strongly disapprove of it.","ex":{"en":"The ethics committee may take a decision to admonish him or to censure him","cn":"道德委员会也许会决定对他进行训诫或是严厉批评。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act of expressing strong disapproval and criticism","cn":"严厉批评﹐谴责"},{"en":"to officially criticize someone for something they have done wrong","cn":"正式谴责[批评]"}]},"vocab":{"pos":"n v","senses":[{"en":"Censure is a noun referring to very strong criticism; the verb means to criticize very strongly. If you take your dad's car without telling him, you can expect him to censure you severely, and maybe even ground you as well."}]},"collocations":{"phrases":["ADV. severely The manager was severely censured for negligence.","PREP. for"]},"media":{"uk":"media/ldoce/hwd/bre/5/censure_v0205.mp3","us":"media/ldoce/hwd/ame/4/censure1.mp3"},"examples":[{"en":"He was censured for leaking information to the press.","cn":"他因泄露消息给新闻界而受到谴责。"},{"en":"a vote of censure on the government's foreign policy","cn":"投票表决谴责政府的外交政策"}],"oxford":{"phon":"ˈsenʃə(r)","pos":"noun","senses":[{"en":"strong criticism","cn":"严厉的批评；斥责；谴责","ex":{"en":"The opposition forced a vote of censure on the government's foreign policy.","cn":"反对派迫使政府对政府的外交政策进行谴责票。"}},{"en":"to criticize somebody severely, and often publicly, because of something they have done","cn":"（公开地）严厉斥责，谴责","ex":{"en":"He was censured for leaking information to the press.","cn":"他因泄露消息给新闻界而受到谴责。"},"pos":"verb"}]}},"ceremonial":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"仪式的;礼节的","en":"Something that is ceremonial relates to a ceremony or is used in a ceremony.","ex":{"en":"He represented the nation on ceremonial occasions","cn":"他在正式场合代表国家。"}},{"pos":"ADJ 形容词","cn":"(职位、功能或事件)礼仪性的，象征性的","en":"A position, function, or event that is ceremonial is considered to be representative of an institution, but has very little authority or influence.","ex":{"en":"Up to now the post of president has been largely ceremonial.","cn":"到目前为止，总统一职在很大程度上只是礼仪性的。"}},{"pos":"N-VAR 可变名词","cn":"仪式;典礼;礼节","en":"Ceremonial consists of all the impressive things that are done, said, and worn on very formal occasions.","ex":{"en":"...papal ceremonial.","cn":"教皇加冕仪式"}},{"pos":"N-COUNT 可数名词","cn":"同 ceremony","en":"A ceremonial is a ceremony.","ex":{"en":"...a religious ceremonial.","cn":"宗教仪式"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a special formal event which is part of the religious or social tradition of a place, and in which there is a fixed set of words and actions","cn":""},{"en":"ceremonial clothes, objects, and activities are used in important religious or social ceremonies","cn":""},{"en":"a set of words and actions that are always done in the same way, for example as part of a religious ceremony","cn":""}]},"collocations":{"phrases":["VERBS be","ADV. purely The monarch's role is purely ceremonial. | essentially, largely, primarily"]},"media":{"uk":"media/ldoce/hwd/bre/e/ceremonial_adj0205.mp3","us":"media/ldoce/hwd/ame/2/ceremonial1.mp3"},"examples":[{"en":"The visit was conducted with all due ceremonial.","cn":"访问按照一切应有的礼仪进行。"},{"en":"ceremonial occasions","cn":"礼仪场合"}],"oxford":{"phon":"ˌserɪˈməʊniəl","pos":"adjective","senses":[{"en":"relating to or used in a ceremony","cn":"礼仪的；礼节的；用于礼仪的","ex":{"en":"ceremonial occasions","cn":"礼仪场合"}},{"en":"the system of rules and traditions that states how things should be done at a ceremony or formal occasion","cn":"礼仪；礼节","ex":{"en":"The visit was conducted with all due ceremonial.","cn":"访问按照一切应有的礼仪进行。"},"pos":"noun"}]}},"centenary":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"一百周年纪念","en":"The centenary of an event such as someone's birth is the 100th anniversary of that event.","ex":{"en":"...the centenary of the death of the Dutch painter, Vincent Van Gogh.","cn":"荷兰画家凡·高逝世一百周年纪念"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the day or year exactly 100 years after a particular event","cn":"一百周年（纪念）"}]},"collocations":{"phrases":["VERB + CENTENARY celebrate, commemorate, mark The club will hold a party to celebrate its centenary.","CENTENARY + NOUN celebrations, year"]},"media":{"uk":"media/ldoce/hwd/bre/e/centenary0205.mp3","us":"media/ldoce/hwd/ame/a/ld41centenary.mp3"},"examples":[{"en":"The club will celebrate its centenary next year.","cn":"俱乐部明年要庆祝成立一百周年。"},{"en":"the centenary year","cn":"一百周年纪念年"}],"oxford":{"phon":"senˈtiːnəri","pos":"noun","senses":[{"en":"the 100th anniversary of an event","cn":"100 周年纪念","ex":{"en":"The club will celebrate its centenary next year.","cn":"俱乐部明年要庆祝成立一百周年。"}}]}},"centimetre":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"厘米","en":"A centimetre is a unit of length in the metric system equal to ten millimetres or one-hundredth of a metre.","ex":{"en":"...a tiny fossil plant, only a few centimetres high.","cn":"一株很小的化石植物，只有几厘米高"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a unit for measuring length. There are 100 centimetres in one metre.","cn":"厘米"}]},"media":{"uk":"media/ldoce/hwd/bre/4/centimetre0205.mp3","us":"media/ldoce/hwd/ame/1/centimeter.mp3"},"oxford":{"phon":"ˈsentɪmiːtə(r)","pos":"noun","senses":[{"en":"a unit for measuring length. There are 100 centimetres in a metre.","cn":"厘米"}]}},"celebrity":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指娱乐界的)名人，明星","en":"A celebrity is someone who is famous, especially in areas of entertainment such as films, music, writing, or sport.","ex":{"en":"In 1944, at the age of 30, Hersey suddenly became a celebrity.","cn":"1944年，30岁的赫西一夜成名。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指娱乐界的)名声，名誉，名气","en":"If a person or thing achieves celebrity, they become famous, especially in areas of entertainment such as films, music, writing, or sport.","ex":{"en":"Joanna has finally made it to the first rank of celebrity after 25 years as an actress.","cn":"乔安娜当了25年演员后，终于跻身一线女明星之列。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a very famous and successful actor, entertainer, or sports player","cn":""},{"en":"someone who is well known, for example as an entertainer or sports player, and who is often seen on television or written about in newspapers","cn":""},{"en":"an actor, musician, or sports player who is famous all over the world","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A celebrity is a very famous person. If you single-handedly save an entire family from a burning building, you'll become a local celebrity ."}]},"collocations":{"phrases":["ADJ. minor | local, international, national | overnight | guest, visiting | showbiz, sporting, television","QUANT. host Tonight's show features a host of celebrities.","VERB + CELEBRITY make sb The show's success made her an overnight celebrity.","CELEBRITY + NOUN status | chef","PHRASES something of a celebrity He became something of a celebrity in his home town."]},"media":{"uk":"media/ldoce/hwd/bre/a/celebrity0205.mp3","us":"media/ldoce/hwd/ame/c/celebrity.mp3"},"examples":[{"en":"Does he find his new celebrity intruding on his private life?","cn":"他是否感觉到他最近的成名侵扰了他的私生活？"},{"en":"TV celebrities","cn":"电视名人"}],"oxford":{"phon":"səˈlebrəti","pos":"noun","senses":[{"en":"a famous person","cn":"名人；名流","g":"[countable]","lab":"informal","ex":{"en":"a celebrity chef","cn":"明星厨师"}},{"en":"the state of being famous","cn":"名望；名誉；著名","g":"[uncountable]","ex":{"en":"Does he find his new celebrity intruding on his private life?","cn":"他是否感觉到他最近的成名侵扰了他的私生活？"}}]}},"cemetery":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"墓地;公墓;坟场","en":"A cemetery is a place where dead people's bodies or their ashes are buried."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of land, usually not belonging to a church, in which dead people are buried 〔","cn":"通常不属于某个教堂的〕公墓﹐墓地"}]},"vocab":{"pos":"n","senses":[{"en":"A cemetery is the land used for burials. If you are 11 and you purchase a plot in a cemetery , you are planning too far ahead."}]},"collocations":{"phrases":["ADJ. local | private, public He was buried in a private cemetery. | military | Catholic, Jewish, etc.","VERB + CEMETERY be buried in | visit","PREP. in a/the ~"]},"media":{"uk":"media/ldoce/hwd/bre/0/cemetery0205.mp3","us":"media/ldoce/hwd/ame/3/cemetery.mp3"},"oxford":{"phon":"ˈsemətri","pos":"noun","senses":[{"en":"an area of land used for burying dead people, especially one that is not next to a church","cn":"（尤指不紧靠教堂的）墓地，坟地，公墓","ex":{"en":"He was buried in a private cemetery.","cn":"他埋在私人墓地。"}}]}},"cease":{"collins":{"senses":[{"pos":"VERB 动词","cn":"停止;终了;消失","en":"If something ceases, it stops happening or existing.","ex":{"en":"At one o'clock the rain had ceased.","cn":"一点时，雨已停了。"}},{"pos":"VERB 动词","cn":"停止;终止","en":"If you cease to do something, you stop doing it.","ex":{"en":"He never ceases to amaze me","cn":"他总能给我惊喜。"}},{"pos":"VERB 动词","cn":"停止;终止","en":"If you cease something, you stop it happening or working.","ex":{"en":"The Tundra Times, a weekly newspaper in Alaska, ceased publication this week.","cn":"阿拉斯加的周报《苔原时报》本周停刊了。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to not do something any longer","cn":""},{"en":"to stop doing something","cn":"禁止"},{"en":"to stop doing something, especially something that you have been doing for a long time","cn":""}]},"vocab":{"pos":"v n","senses":[{"en":"\"Cease to exist\" is a popular use of the word cease , or end, and you may have closed your eyes and wished that someone — the boogeyman in the dark or a pesky sibling by day — would stop! Go away! Cease to be! Or, at the very least — quit bugging you."}]},"collocations":{"phrases":["ADV. altogether, completely, entirely The flow slowed, then ceased altogether. | all but, almost, virtually | largely | effectively My job h","PREP. with The matches ceased with the outbreak of war.","PHRASES without ceasing Prayer was made without ceasing."]},"media":{"uk":"media/ldoce/hwd/bre/b/cease_v0205.mp3","us":"media/ldoce/hwd/ame/8/cease1.mp3"},"examples":[{"en":"Welfare payments cease as soon as an individual starts a job.","cn":"一旦就业，即停发福利救济。"},{"en":"They voted to cease strike action immediately.","cn":"他们投票决定立即停止罢工。"}],"oxford":{"phon":"siːs","pos":"verb","senses":[{"en":"to stop happening or existing; to stop something from happening or existing","cn":"（使）停止，终止，结束","ex":{"en":"Welfare payments cease as soon as an individual starts a job.","cn":"一旦就业，即停发福利救济。"}}]}},"censorship":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(尤指政府官员对书刊、戏剧、电影、报道等的)审查，检查","en":"Censorship is the censoring of books, plays, films, or reports, especially by government officials, because they are considered immoral or secret in some way.","ex":{"en":"The government today announced that press censorship was being lifted.","cn":"政府今天宣布将取消新闻审查制度。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to forbid a book, film, play etc from being sold, seen, performed etc because it is considered morally harmful or politically dangerous","cn":""},{"en":"to examine films, books, letters etc and take out any parts that are considered to be morally harmful or politically dangerous","cn":""},{"en":"the practice of officially examining films, books, letters etc to take out any parts which are considered to be morally harmful or politically dangerous","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Censorship blocks something from being read, heard, or seen. If you've ever heard the sound of bleeping when someone is speaking on television, that's censorship ."}]},"collocations":{"phrases":["ADJ. strict | government, military, state, wartime | film, media, political, press","VERB + CENSORSHIP impose The government has imposed strict censorship on the press. | abolish, lift | tighten Political censorship has been "]},"media":{"uk":"media/ldoce/hwd/bre/e/censorship0205.mp3","us":"media/ldoce/hwd/ame/6/censorship.mp3"},"examples":[{"en":"The decree imposed strict censorship of the media.","cn":"这个法令强制实行严格的媒体审查制度。"},{"en":"press censorship","cn":"新闻审查制度"}],"oxford":{"phon":"ˈsensəʃɪp","pos":"noun","senses":[{"en":"the act or policy of censoring books, etc.","cn":"审查；检查；审查制度","ex":{"en":"press censorship","cn":"新闻审查制度"}}]}},"censor":{"collins":{"senses":[{"pos":"VERB 动词","cn":"审查，检查(书信或媒体)","en":"If someone in authority censors letters or the media, they officially examine them and cut out any information that is regarded as secret.","ex":{"en":"The military-backed government has heavily censored the news.","cn":"有军方撑腰的政府对新闻进行了严格审查。"}},{"pos":"N-COUNT 可数名词","cn":"（书信或媒体的）审查官，监察员","en":"A censor is a person who has been officially appointed to examine letters or the media and to cut out any parts that are regarded as secret.","ex":{"en":"The report was cleared by the American military censors.","cn":"那篇报道得到美国军方审查官的批准。"}},{"pos":"VERB 动词","cn":"审查，检查(书刊、戏剧或电影等)","en":"If someone in authority censors a book, play, or film, they officially examine it and cut out any parts that are considered to be immoral or inappropriate.","ex":{"en":"The Late Show censored the band's live version of 'Bullet In The Head'","cn":"《深夜秀》节目删掉了乐队的《爆头》现场版。"}},{"pos":"N-COUNT 可数名词","cn":"(书刊、戏剧或电影)审查官，检查员","en":"A censor is a person who has been officially appointed to examine plays, films, and books and to cut out any parts that are considered to be immoral.","ex":{"en":"...the British Board of Film Censors.","cn":"英国电影审查委员会"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to forbid a book, film, play etc from being sold, seen, performed etc because it is considered morally harmful or politically dangerous","cn":""},{"en":"to examine films, books, letters etc and take out any parts that are considered to be morally harmful or politically dangerous","cn":""},{"en":"the practice of officially examining films, books, letters etc to take out any parts which are considered to be morally harmful or politically dangerous","cn":""}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A censor takes out things that are objectionable or inappropriate, like the censors at the TV networks bleeping out all the bad words in a show."}]},"collocations":{"phrases":["ADV. heavily The film has been heavily censored."]},"media":{"uk":"media/ldoce/hwd/bre/4/censor_n0205.mp3","us":"media/ldoce/hwd/ame/9/censor1.mp3"},"examples":[{"en":"The news reports had been heavily censored.","cn":"这些新闻报道已被大肆删剪。"},{"en":"The information given to the press was carefully censored by the Ministry of Defence.","cn":"发给报界的信息经过了国防部的仔细审查。"}],"oxford":{"phon":"ˈsensə(r)","pos":"noun","senses":[{"en":"a person whose job is to examine books, films, etc. and remove parts that are considered to be offensive or a political threat","cn":"（书、电影等的）审查员，审查官"},{"en":"to remove the parts of a book, film, etc. that are considered to be offensive or a political threat","cn":"删剪（书、电影等中被认为犯忌或政治上危险的内容）","ex":{"en":"The news reports had been heavily censored.","cn":"这些新闻报道已被大幅删剪。"},"pos":"verb"}]}},"certificate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"证明;证书","en":"A certificate is an official document stating that particular facts are true.","ex":{"en":"...birth certificates.","cn":"出生证明"}},{"pos":"N-COUNT 可数名词","cn":"结业证书;合格证书;文凭","en":"A certificate is an official document that you receive when you have completed a course of study or training. The qualification that you receive is sometimes also called a certificate .","ex":{"en":"To the right of the fireplace are various framed certificates.","cn":"壁炉的右边是各种镶框的证书。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official document that states that a fact or facts are true","cn":"证明书﹐证书"},{"en":"an official paper stating that you have completed a course of study or passed an examination （","cn":"毕业）文凭﹐合格证书"}]},"vocab":{"pos":"n v","senses":[{"en":"A certificate is a paper or document that proves some fact. Your proudest possession might be the certificate you got when you became a black belt in karate."}]},"collocations":{"phrases":["ADJ. birth, death, marriage | medical | school, school-leaving","VERB + CERTIFICATE award (sb), issue The police are waiting for the doctor to issue a death certificate.","PREP. ~ of a certificate of motor insurance"]},"media":{"img":["media/ldoce/img/certificate.jpg"],"uk":"media/ldoce/hwd/bre/0/brelasdecertificate.mp3","us":"media/ldoce/hwd/ame/a/certificate.mp3"},"examples":[{"en":"a Postgraduate Certificate in Education (= a British qualification for teachers)","cn":"教育学研究生证书（英国教师资格证书）"},{"en":"a birth/marriage/death certificate","cn":"出生/结婚/死亡证明"}],"oxford":{"phon":"səˈtɪfɪkət","pos":"noun","senses":[{"en":"an official document that may be used to prove that the facts it states are true","cn":"证明；证明书","ex":{"en":"a birth/marriage/death certificate","cn":"出生／结婚／死亡证明"}},{"en":"an official document proving that you have completed a course of study or passed an exam; a qualification obtained after a course of study or an exam","cn":"文凭；结业证书；合格证书","ex":{"en":"a Postgraduate Certificate in Education (= a British qualification for teachers)","cn":"教育学研究生证书（英国教师资格证书）"}},{"en":"to give somebody an official document proving that they have successfully completed a training course, especially for a particular profession","cn":"发给结业证书；（尤指）发给职业培训证书","pos":"verb"}]}},"cello":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"大提琴","en":"A cello is a musical instrument with four strings that looks like a large violin. You play the cello with a bow while sitting down and holding it upright between your legs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a musical instrument like a large violin that you hold between your knees and play by pulling a bow (= special stick ) across the strings","cn":"大提琴"}]},"media":{"img":["media/ldoce/img/cello.jpg","media/thumb/cello.jpg"],"uk":"media/ldoce/hwd/bre/a/cello0205.mp3","us":"media/ldoce/hwd/ame/7/cello.mp3"},"oxford":{"phon":"ˈtʃeləʊ","pos":"noun","senses":[{"en":"a musical instrument with strings, like a large violin in shape. The player sits down and holds the cello between his or her knees.","cn":"大提琴"}]}},"census":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"人口普查","en":"A census is an official survey of the population of a country that is carried out in order to find out how many people live there and to obtain details of such things as people's ages and jobs."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an official process of counting a country’s population and finding out about the people","cn":"人口普查"},{"en":"an official process of counting something for government planning 〔","cn":"官方进行的〕统计﹐调查"}]},"vocab":{"pos":"n v","senses":[{"en":"If you live in the U.S., every ten years you'll participate in a census, a process for counting people. The information collected is used to plan for schools, transportation, social services people will need, and also for determining congressional districts."}]},"collocations":{"phrases":["ADJ. complete, full | general, national, official | decennial | population","VERB + CENSUS carry out, conduct, take A national census is taken every ten years.","CENSUS + NOUN data, figures, records, results, return, statistics","PREP. in a/the ~ the questions asked in the census"]},"media":{"uk":"media/ldoce/hwd/bre/4/census0205.mp3","us":"media/ldoce/hwd/ame/b/census.mp3"},"examples":[{"en":"a traffic census","cn":"交通状况调查"}],"oxford":{"phon":"ˈsensəs","pos":"noun","senses":[{"en":"the process of officially counting something, especially a country’s population, and recording various facts","cn":"（官方的）统计；人口普查；人口调查","ex":{"en":"to take a census","cn":"进行人口普查"}}]}},"cereal":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"(拌以牛奶作早餐的)谷类食品，麦片","en":"Cereal or breakfast cereal is a food made from grain. It is mixed with milk and eaten for breakfast.","ex":{"en":"I have a bowl of cereal every morning.","cn":"我每天早上喝一碗麦片。"}},{"pos":"N-COUNT 可数名词","cn":"谷类作物;谷物","en":"Cereals are plants such as wheat, corn, or rice that produce grain.","ex":{"en":"...the rich cereal-growing districts of the Paris Basin.","cn":"巴黎盆地盛产谷物的地区"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a breakfast food made from grain and usually eaten with milk 〔","cn":"通常与牛奶一起吃的〕谷类早餐食物﹐麦片"},{"en":"a plant grown to produce grain, for example wheat, rice etc","cn":"谷类植物﹐谷物"}]},"collocations":{"phrases":["VERB + CEREAL grow, produce | harvest","CEREAL + NOUN crop, foods, products | farmer, grower, producer | production 2 food","ADJ. fortified fortfied breakfast cereals | breakfast | bran, wholegrain, wholewheat","QUANT. bowl a big bowl of cereal | packet","VERB + CEREAL eat, have having cereal for breakfast","CEREAL + VERB be fortified a wholewheat cereal fortified with B group vitamins","CEREAL + NOUN bowl, packet"]},"media":{"img":["media/ldoce/img/bowl_cereal.jpg"],"uk":"media/ldoce/hwd/bre/0/cereal0205.mp3","us":"media/ldoce/hwd/ame/3/cereal.mp3"},"examples":[{"en":"breakfast cereals","cn":"谷类早餐食物"},{"en":"a bowl of cereal","cn":"一碗麦片粥"}],"oxford":{"phon":"ˈsɪəriəl","pos":"noun","senses":[{"en":"one of various types of grass that produce grains that can be eaten or are used to make flour or bread. wheat, barley and rye are all cereals.","cn":"谷类植物","g":"[countable]","ex":{"en":"cereal crops","cn":"谷类作物"}},{"en":"the grain produced by cereal crops","cn":"谷物","g":"[uncountable]"},{"en":"food made from the grain of cereals, often eaten for breakfast with milk","cn":"（常加牛奶作早餐的）谷类食物","g":"[countable, uncountable]","ex":{"en":"breakfast cereals","cn":"谷类早餐食物"}}]}},"cellphone":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"同 cellular phone","en":"A cellphone is the same as a cellular phone ."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a cellular phone","cn":"移动电话﹐手机"}]},"media":{"uk":"media/ldoce/hwd/bre/3/ld41cellphone.mp3","us":"media/ldoce/hwd/ame/3/ld41cellphone.mp3"}}});
